const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const t = tok[0];
const MAXS = 160;
const cnt = Array.from({ length: 18 }, () => new Array(MAXS + 1).fill(0));
cnt[0][0] = 1;
for (let k = 1; k < 18; k++)
  for (let s = 0; s <= MAXS; s++) {
    let v = 0;
    for (let d = 0; d < 10 && s - d >= 0; d++) v += cnt[k - 1][s - d];
    cnt[k][s] = v;
  }
function f(n, S) {
  if (n < 0) return 0;
  const digs = String(n).split("").map(Number);
  const L = digs.length;
  let pre = 0, total = 0;
  for (let i = 0; i < L; i++) {
    const rem = L - i - 1;
    for (let c = 0; c < digs[i]; c++) {
      const need = S - pre - c;
      if (need >= 0 && need <= MAXS) total += cnt[rem][need];
    }
    pre += digs[i];
  }
  if (pre === S) total += 1;
  return total;
}
const out = [];
for (let i = 0; i < t; i++) {
  const l = tok[1 + 3 * i], r = tok[2 + 3 * i], s = tok[3 + 3 * i];
  out.push(f(r, s) - f(l - 1, s));
}
console.log(out.join("\n"));

