import java.io.*;
import java.util.*;

public class Main {
    static final int MAXS = 160;
    static long[][] cnt = new long[18][MAXS + 1];

    static long f(long n, int S) {
        if (n < 0) return 0;
        String str = Long.toString(n);
        int L = str.length(), pre = 0;
        long total = 0;
        for (int i = 0; i < L; i++) {
            int d = str.charAt(i) - '0', rem = L - i - 1;
            for (int c = 0; c < d; c++) {
                int need = S - pre - c;
                if (need >= 0 && need <= MAXS) total += cnt[rem][need];
            }
            pre += d;
        }
        if (pre == S) total++;
        return total;
    }

    public static void main(String[] args) throws IOException {
        cnt[0][0] = 1;
        for (int k = 1; k < 18; k++)
            for (int s = 0; s <= MAXS; s++)
                for (int d = 0; d < 10 && s - d >= 0; d++) cnt[k][s] += cnt[k - 1][s - d];
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int t = Integer.parseInt(st.nextToken());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < t; i++) {
            st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken()), r = Long.parseLong(st.nextToken());
            int s = Integer.parseInt(st.nextToken());
            out.append(f(r, s) - f(l - 1, s)).append('\n');
        }
        System.out.print(out);
    }
}

